from collections import deque

def comps_zero(g):
 h,w=len(g),len(g[0]); seen=set(); res=[]
 for r in range(h):
  for c in range(w):
   if g[r][c]!=0 or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); co=[]
   for x,y in q:
    co.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     a,b=x+dx,y+dy
     if 0<=a<h and 0<=b<w and g[a][b]==0 and (a,b) not in seen:
      seen.add((a,b)); q.append((a,b))
   res.append(co)
 return res
